	script.Parent.Activated:Connect(function()
		if toggle == false then
			toggle = true
			script.Parent.Text = "Disable Grab Tools"
		else
			toggle = false
			script.Parent.Text = "Enable Grab Tools"
		end
	end)
	while task.wait() do
		if toggle == true then
			for _, tool in ipairs(game:GetService("Workspace"):GetDescendants()) do
				if tool.ClassName == "Tool" then
					if tool.Parent ~= game:GetService("Players").LocalPlayer.Character then
						if tool:FindFirstChild("Handle") then
							local function xd()
								tool.Parent:FindFirstChildWhichIsA("Humanoid").Name = tool.Parent:FindFirstChildWhichIsA("Humanoid").Name
							end
							if pcall(xd) == false then
								game:GetService("Players").LocalPlayer.Character:FindFirstChildWhichIsA("Humanoid"):EquipTool(tool)
								local origpos = game:GetService("Players").LocalPlayer.Character.HumanoidRootPart.CFrame
								game:GetService("Players").LocalPlayer.Character:FindFirstChildWhichIsA("Humanoid"):EquipTool(tool)
								game:GetService("Players").LocalPlayer.Character:FindFirstChildWhichIsA("Humanoid").PlatformStand = true
								game:GetService("Players").LocalPlayer.Character:FindFirstChildWhichIsA("Humanoid"):EquipTool(tool)
								game:GetService("Players").LocalPlayer.Character.HumanoidRootPart.CFrame = tool.Handle.CFrame
								game:GetService("Players").LocalPlayer.Character:FindFirstChildWhichIsA("Humanoid"):EquipTool(tool)
								task.wait(0.015)
								game:GetService("Players").LocalPlayer.Character:FindFirstChildWhichIsA("Humanoid"):EquipTool(tool)
								game:GetService("Players").LocalPlayer.Character.HumanoidRootPart.CFrame = origpos
								game:GetService("Players").LocalPlayer.Character:FindFirstChildWhichIsA("Humanoid"):EquipTool(tool)
								game:GetService("Players").LocalPlayer.Character:FindFirstChildWhichIsA("Humanoid").PlatformStand = false
								game:GetService("Players").LocalPlayer.Character:FindFirstChildWhichIsA("Humanoid"):EquipTool(tool)
								game:GetService("Players").LocalPlayer.Character.HumanoidRootPart.AssemblyAngularVelocity = Vector3.new(0,0,0)
								game:GetService("Players").LocalPlayer.Character:FindFirstChildWhichIsA("Humanoid"):EquipTool(tool)
								game:GetService("Players").LocalPlayer.Character.HumanoidRootPart.AssemblyLinearVelocity = Vector3.new(0,0,0)
								game:GetService("Players").LocalPlayer.Character:FindFirstChildWhichIsA("Humanoid"):EquipTool(tool)
							end
						end
					end
				end
			end
		end
	end



end;
task.spawn(C_1d);
