				for i,v in pairs(Windows) do
					count = 0
					if i ~= wName then
						for _,c in pairs(v) do c:TweenPosition(UDim2.new(1, 30, count * 0.5, count * 36), "Out", "Quad", 0.5, true) count = count + 1 end
					end
				end

