				if readOnly then
					colorBox.AutoButtonColor = false
				end

				local spacingBefore = (Styles.Margin * 2) + BrickColors.BoxSize

				local propertyLabel = CreateTextButton(readOnly, function()
					if not readOnly then
						toggle()
					end
				end)
