							end
							newTab:Destroy()
						end
					end
				end)

				editingIndex = #memoryScripts
				buildScript(scrSource,0,0,true)

				newTab.Parent = scriptBar
			end

			function updateScriptBar()
				local entryCount = 0

				scriptBarLeft.Active = false
